    R.rimL=mk('path',rs,m);R.rimR=mk('path',Object.assign({transform:'translate(525 0) scale(-1 1)'},rs),m);
    mk('rect',{x:59,y:257,width:406,height:13,fill:'#000'},m);
    m=mask('line');
    R.lnL=box(mk('rect',{x:59,y:257,width:204,height:13,fill:'#fff'},m),'100% 50%');
    R.lnR=box(mk('rect',{x:263,y:257,width:202,height:13,fill:'#fff'},m),'0% 50%');
    m=mask('pgL');R.pmL=box(mk('rect',{x:95,y:110,width:168,height:145,fill:'url(#'+P+'lf)'},m),'100% 50%');
    m=mask('pgR');R.pmR=box(mk('rect',{x:263,y:110,width:168,height:145,fill:'url(#'+P+'rt)'},m),'0% 50%');
    R.wipe={};for(const n of ['wA','wB','wC']){const mm=mask(n);R.wipe[n]=mk('rect',{x:-730,y:0,width:1250,height:645,fill:'url(#'+P+'fw)'},mm);}
    m=mask('torch');R.tm=mk('rect',{x:195,y:320,width:135,height:250,fill:'url(#'+P+'up)'},m);
    m=mask('flA');R.fmA=mk('rect',{x:200,y:215,width:125,height:150,fill:'url(#'+P+'up)'},m);
    m=mask('flB');R.fmB=mk('rect',{x:200,y:215,width:125,height:150,fill:'url(#'+P+'up)'},m);
    R.leaf=LEAVES.map((row,i)=>[0,2].map(j=>{const mm=mask('lf'+i+j),st=row[j+1],g=mk('g',{transform:'translate('+st[0]+' '+st[1]+') rotate('+(j?320:220)+')'},mm);return mk('rect',{x:-320,y:-260,width:320,height:520,fill:'url(#'+P+'fw)'},g);}));
