    this.dup=layer(svg,'shield','line').parentNode;
    D.nameA={fill:D.name.fill,p:D.name.p.slice(0,12)};D.nameB={fill:D.name.fill,p:D.name.p.slice(12)};R.nameA=layer(svg,'nameA','wA');R.nameB=layer(svg,'nameB','wB');
    layer(svg,'torch','torch');
    R.city=layer(svg,'city','wC');
    R.pageL=box(layer(svg,'pageL','pgL'),'100% 100%');
    R.pageR=box(layer(svg,'pageR','pgR'),'0% 100%');
    for(let i=0;i<3;i++)if(i!==1){layer(svg,LEAVES[i][0],'lf'+i+'0');layer(svg,LEAVES[i][2],'lf'+i+'2');}
    
