    add(R.pageL,{transform:['scale(0.93,0.985)','scale(1,1)']},0.45,0.8);
    add(R.pageR,{transform:['scale(0.93,0.985)','scale(1,1)']},0.45,0.8);
    add(R.lnL,sx,0.5,0.75);add(R.lnR,sx,0.5,0.75);
    add(R.tm,{transform:['translateY(250px)','translateY(0px)']},0.8,0.65);
    R.leaf.forEach((pair,i)=>pair.forEach(r=>add(r,{transform:['translateX(0px)','translateX(300px)']},1+i*0.085,0.68)));
    const up={transform:['translateY(150px)','translateY(0px)']},gr={transform:['scaleY(0.96)','scaleY(1)']};
